# (чтение) есть ли в базе удержание недостачи Дуйсенбаев/Жусупов (Дт1255 Кт6280, Дт3350 Кт1255) и сальдо 1255/3350 по ним
for r in q('ВЫБРАТЬ Х.Регистратор КАК Р, Х.Период КАК П, Х.СчетДт.Код КАК Дт, Х.СчетКт.Код КАК Кт, Х.Сумма КАК С, Х.СубконтоДт1 КАК СД, Х.СубконтоКт1 КАК СК ИЗ РегистрБухгалтерии.{REG}.ДвиженияССубконто(, , СчетДт.Код = "1255" ИЛИ СчетКт.Код = "1255", , ) КАК Х'):
    print(' ', str(r['П'])[:10], r['Дт'], r['Кт'], f"{float(r['С']):,.2f}", s(r['СД'])[:25], '|', s(r['СК'])[:25], '|', s(r['Р'])[:50])
for r in q('ВЫБРАТЬ Т.Субконто1 КАК К, Т.Организация КАК О, Т.СуммаОстаток КАК С ИЗ РегистрБухгалтерии.{REG}.Остатки(&Д, Счет.Код = "3350", , ) КАК Т ГДЕ Т.Субконто1.Наименование ПОДОБНО "%Дуйсенба%" ИЛИ Т.Субконто1.Наименование ПОДОБНО "%Жусупов%"', Д=datetime.datetime(2026, 10, 27)):
    print('  3350', s(r['К'])[:30], s(r['О'])[:25], f"{float(r['С'] or 0):,.2f}")
